      <main>
        <Hero />
        <ProductSection id="new" title="Featured Products" products={featuredProducts} isDeal={false} />
        <EditorialSection />
        <ProductSection id="deals" title="Special Deals" products={deals} isDeal={true} />
      </main>
      <Footer />
    </div>
  );
};

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(<App />);
